#include <iostream>
#include <vector>
#include <algorithm>
#define INF 2100000000
using namespace std;

int minix(int a, int b, int c) {
    return min(a, min(b, c)); // Simplified to use std::min for clarity
}

int main() {
    int n;
    while (scanf("%d", &n) && n != 0) {
        vector<vector<int>> masu(n + 1, vector<int>(n + 1, 0)); // Using vector for dynamic memory allocation
        vector<vector<int>> ura(n + 1, vector<int>(n + 1, 0));
        string str;

        for (int i = 1; i <= n; i++) {
            cin >> str; // Using cin to read the string directly
            for (int j = 1; j <= n; j++)
                ura[i][j] = (str[j - 1] == '.') ? 0 : 1;
        }

        int maxi = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (ura[i][j] == 0) {
                    masu[i][j] = minix(masu[i - 1][j], masu[i][j - 1], masu[i - 1][j - 1]) + 1;
                    maxi = max(masu[i][j], maxi);
                }
            }
        }

        printf("%d\n", maxi);
    }
}

